/* La Favorita V6 — tienda multipágina */
const $=(q,root=document)=>root.querySelector(q);
const $$=(q,root=document)=>Array.from(root.querySelectorAll(q));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'S/ '+Number(n||0).toFixed(2);
const fold=v=>String(v??'').toLocaleLowerCase('es').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^\w\s]/g,' ').replace(/\s+/g,' ').trim();
const kindIcon={search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4.2-4.2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',arrowup:'<path d="M7 17 17 7M8 7h9v9"/>',bag:'<path d="M5 8h14l-1 12H6L5 8ZM9 8V6a3 3 0 0 1 6 0v2"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',spark:'<path d="m12 2 2.4 7.6L22 12l-7.6 2.4L12 22l-2.4-7.6L2 12l7.6-2.4L12 2Z"/>',stars:'<path d="m8 3 1.5 4.5L14 9l-4.5 1.5L8 15l-1.5-4.5L2 9l4.5-1.5L8 3ZM18 13l1 3 3 1-3 1-1 3-1-3-3-1 3-1 1-3Z"/>',compare:'<path d="M3 7h14M3 17h18M13 3l4 4-4 4M11 13l-4 4 4 4"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',close:'<path d="M5 5l14 14M19 5 5 19"/>',plus:'<path d="M12 5v14M5 12h14"/>',minus:'<path d="M5 12h14"/>',check:'<path d="m4 12 5 5L20 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',filter:'<path d="M4 5h16M7 12h10M10 19h4"/>',chevron:'<path d="m8 10 4 4 4-4"/>',back:'<path d="m15 5-7 7 7 7"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 17v4h16v-4"/>',file:'<path d="M6 3h8l5 5v13H6Z M14 3v6h5M9 14h7M9 18h7"/>',copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>',phone:'<path d="M6 3h4l2 5-3 2a15 15 0 0 0 5 5l2-3 5 2v4c0 2-2 3-4 3A17 17 0 0 1 3 7c0-2 1-4 3-4Z"/>',heart:'<path d="M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-4 4 0 9 8 15 8-6 12-11 8-15Z"/>',box:'<path d="m3 7 9-4 9 4v10l-9 4-9-4V7Zm0 0 9 4 9-4M12 11v10"/>',shield:'<path d="m12 2 8 4v6c0 5-3 8-8 10-5-2-8-5-8-10V6l8-4Z"/><path d="m8 12 3 3 5-6"/>',gift:'<rect x="3" y="9" width="18" height="12" rx="2"/><path d="M3 13h18M12 9v12M12 9c-8 0-7-8-3-7 2 0 3 4 3 7Zm0 0c8 0 7-8 3-7-2 0-3 4-3 7Z"/>',pencil:'<path d="m4 18 11-11 3 3-11 11-4 1 1-4ZM13 9l3-3 3 3-3 3"/>',book:'<path d="M4 4h13a3 3 0 0 1 3 3v14H7a3 3 0 0 1-3-3V4Zm0 0v14a3 3 0 0 0 3 3M8 9h7M8 13h7"/>',palette:'<path d="M12 3a9 9 0 1 0 9 9c0-2-2-2-4-2s-2-2-2-4c0-1-1-3-3-3Z"/><circle cx="7" cy="10" r="1"/><circle cx="10" cy="6.5" r="1"/><circle cx="7" cy="15" r="1"/>',folder:'<path d="M3 6h7l2 2h9v12H3V6Z"/>',glue:'<rect x="7" y="7" width="10" height="14" rx="3"/><rect x="9" y="3" width="6" height="4" rx="1"/>',calculator:'<rect x="5" y="2" width="14" height="20" rx="2"/><path d="M8 6h8v4H8ZM8 14h2m4 0h2m-8 4h2m4 0h2"/>',printer:'<path d="M5 9V3h14v6M5 18H3v-8h18v8h-2M6 14h12v8H6Z"/>',play:'<path d="m8 5 12 7-12 7V5Z"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',alert:'<path d="m12 3 10 18H2L12 3Z"/><path d="M12 9v5M12 18h.01"/>'};
const icon=(id,size=20)=>`<svg class="icon" aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${kindIcon[id]||kindIcon.stars}</svg>`;
const CATEGORY_IMAGES={escritura:'lapiceros',cuadernos:'cuadernos',papel:'papel',pegamentos:'silicona',arte:'arte',oficina:'folders',tecnologia:'calculadora'};
const CATEGORY_ICONS={escritura:'pencil',cuadernos:'book',papel:'folder',pegamentos:'glue',arte:'palette',oficina:'printer',tecnologia:'calculator'};
const SAMPLE_LIST='2 cuaderno A4\n1 plumones escolares x12\n1 silicona líquida 250 ml\n1 corros pun escarchado';
const app={bootstrap:null,shop:null,cart:[],branchId:null,route:null,query:'',category:'all',brand:'all',order:'relevancia',stockOnly:false,compareGroup:'',quoteTier:'equilibrada',quoteResult:null,quoteBusy:false,compareProduct:'',aiStatus:null,menu:false,cartOpen:false,toastTimer:null,loadedAt:0};
const api=async (path,options)=>{const response=await fetch(path,{cache:'no-store',...options});const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.error||'No se pudo conectar con la tienda');return data;};
const urlBranch=(suffix='')=>`/tienda/${encodeURIComponent(app.shop?.branch?.id||app.branchId||'sucursal-1')}${suffix}`;
const productUrl=id=>urlBranch(`/producto/${encodeURIComponent(id)}`);
const categoryName=id=>app.shop?.categories.find(c=>c.id===id)?.name||id;
function currentCartKey(){return 'favorita_lista_v3_'+app.branchId;}
function readCart(){try{app.cart=JSON.parse(localStorage.getItem(currentCartKey())||'[]');if(!Array.isArray(app.cart))app.cart=[];}catch{app.cart=[];}}
function writeCart(){try{localStorage.setItem(currentCartKey(),JSON.stringify(app.cart));}catch{}}
function cartCount(){return app.cart.reduce((t,x)=>t+x.qty,0);}
function artFor(p){const name=fold([p.name,p.subCategory,p.model].join(' '));if(/silicona|goma|pegamento|cola/.test(name))return 'silicona';if(/plumones|marcador|resaltador|colores/.test(name))return 'plumones';if(/boligrafo|lapicero|lapiz|bolig/.test(name))return 'lapiceros';if(/cuaderno|libreta|block/.test(name))return 'cuadernos';if(/papel|resma|bond/.test(name))return 'papel';if(/tijera/.test(name))return 'tijeras';if(/cinta|scotch/.test(name))return 'cintas';if(/post.it|notas/.test(name))return 'notas';if(/pila|bateria/.test(name))return 'pilas';if(/calculador/.test(name))return 'calculadora';if(/folder|archivador|sobre/.test(name))return 'folders';if(/microporoso|corospun|escarchado|cartulina/.test(name))return 'manualidades';return CATEGORY_IMAGES[p.categoryId]||'arte';}
function picture(p,variant=''){const fallback=`/assets/products/${artFor(p)}.svg`;return `<div class="product-image ${variant}"><img loading="lazy" src="${esc(p.imageUrl||fallback)}" alt="${esc(p.name)}" data-fallback="${esc(fallback)}"><span class="image-kind">${p.imageUrl?'Foto de catálogo':'Ilustración referencial'}</span></div>`;}
function discount(p){return p.compareAt>p.price?Math.round(100*(p.compareAt-p.price)/p.compareAt):0;}
function offerState(p){return p.stock>10?`<span class="available">${icon('check',13)} Disponible</span>`:p.stock>0?`<span class="few">Quedan ${p.stock}</span>`:'<span class="out">Sin stock</span>';}
function photoHero(){return `<div class="hero-visual" aria-hidden="true"><div class="visual-aura"></div><div class="visual-planet"></div><img class="visual-items" src="/assets/editorial/hero-school.svg" alt=""><div class="floating-pill pill-one">${icon('stars',18)} Tu creatividad empieza aquí</div><div class="floating-pill pill-two">${icon('check',16)} Todo para tus ideas</div><i class="orbit-dot orbit-one"></i><i class="orbit-dot orbit-two"></i></div>`;}
function logo(){return `<a href="/" data-nav class="logo" aria-label="La Favorita, volver al inicio"><img src="/assets/logo-favorita-transparente.png" alt="La Favorita: más que una librería"></a>`;}
function topBar(){return `<div class="utility-bar"><div class="wrap utility-inner"><span>${icon('spark',14)} Papelería, útiles escolares y mucho más</span><span>Selecciona tu sucursal para consultar precios y disponibilidad</span></div></div>`;}
const WHATSAPP_LINK='https://wa.me/51903470891?text='+encodeURIComponent('Hola, quisiera hacer una consulta a La Favorita.');
function branchSwitchUrl(id){
 const page=app.route?.page||'home';
 const suffix=page==='home'||page==='gateway'?'':page==='producto'?`/producto/${encodeURIComponent(app.route.id)}`:`/${encodeURIComponent(page)}`;
 return `/tienda/${encodeURIComponent(id)}${suffix}`;
}
function branchPicker(){
 const branches=app.bootstrap?.branches||app.shop?.branches||[];
 const selected=app.shop?.branch;
 if(!selected)return '';
 return `<div class="branch-switcher" id="branch-switcher"><button id="branch-switch-btn" class="shop-pill" type="button" data-action="switch-branch" aria-haspopup="menu" aria-controls="branch-switch-menu" aria-expanded="false" title="Cambiar de sucursal">${icon('pin',16)}<span>${esc(selected.name)}</span>${icon('chevron',15)}</button><div class="branch-switch-menu" id="branch-switch-menu" role="menu" aria-label="Seleccionar sucursal" hidden><div class="switch-menu-title">Elige una sucursal</div>${branches.map((b,i)=>`<a role="menuitem" class="branch-switch-option ${b.id===selected.id?'selected':''}" href="${branchSwitchUrl(b.id)}" data-nav><img src="${esc(b.photoUrl||`/assets/branches/sucursal-${i+1}.webp`)}" alt="" loading="lazy"><span><b>${esc(b.name)}</b><small>${esc(b.address||'Ver productos de esta tienda')}</small></span>${b.id===selected.id?icon('check',17):icon('arrow',16)}</a>`).join('')}<a class="branch-all-link" data-nav href="/">Ver las cuatro sucursales ${icon('arrow',15)}</a></div></div>`;
}
function whatsappFloat(){return `<a class="whatsapp-float" href="${WHATSAPP_LINK}" target="_blank" rel="noopener noreferrer" aria-label="Contáctanos por WhatsApp al 903 470 891" title="Escríbenos por WhatsApp">${icon('phone',23)}<span>Contáctanos</span></a>`;}
function closeBranchMenu(){const menu=$('#branch-switch-menu');const trigger=$('#branch-switch-btn');if(menu){menu.hidden=true;trigger?.setAttribute('aria-expanded','false');}}
function header(){const shop=!!app.shop;const part=app.route?.page;const branch=app.shop?.branch;
const link=(p,label)=>`<a data-nav class="${part===p?'is-current':''}" href="${urlBranch(p==='home'?'':('/'+p))}">${label}</a>`;
return `${topBar()}<header class="site-header"><div class="scroll-progress" aria-hidden="true"></div><div class="wrap header-content">${logo()}<nav class="desktop-nav" aria-label="Navegación principal"><a data-nav href="/" class="${!shop?'is-current':''}">Inicio</a>${shop?`${link('home','Mi tienda')}${link('catalogo','Productos')}${link('ofertas','Promociones')}${link('comparar','Comparador')}${link('cotizar','Cotización con IA')}`:'<a href="#sucursales" class="nav-simple">Sucursales</a>'}</nav><div class="header-actions"><a class="header-contact" href="${WHATSAPP_LINK}" target="_blank" rel="noopener noreferrer">${icon('phone',16)} <span>Contáctanos</span></a>${shop?`${branchPicker()}<button class="icon-button shopping-bag" data-action="cart" aria-label="Abrir lista de compra">${icon('bag',21)}<b class="cart-count">${cartCount()}</b></button>`:''}<button class="icon-button mobile-toggle" type="button" data-action="toggle-menu" aria-label="Abrir menú">${icon(app.menu?'close':'menu',24)}</button></div></div>${app.menu?`<nav class="mobile-links"><a data-nav href="/">Inicio</a>${shop?`<a data-nav href="${urlBranch()}">Mi sucursal</a><a data-nav href="${urlBranch('/catalogo')}">Productos</a><a data-nav href="${urlBranch('/ofertas')}">Promociones</a><a data-nav href="${urlBranch('/comparar')}">Comparador</a><a data-nav href="${urlBranch('/cotizar')}">Cotizar lista escolar</a><a data-nav href="${urlBranch('/servicios')}">Servicios</a>`:'<a href="#sucursales">Sucursales</a>'}<a class="mobile-contact" href="${WHATSAPP_LINK}" target="_blank" rel="noopener noreferrer">${icon('phone',17)} Contáctanos por WhatsApp</a></nav>`:''}</header>`;}
function footer(){return `<footer class="footer"><div class="wrap footer-top"><div>${logo()}<p>Útiles escolares, oficina, arte y materiales para tus trabajos.</p><div class="footer-social">✦ Hecho con creatividad en Arequipa</div></div><div><h4>Explora</h4><a data-nav href="/">Inicio</a>${app.shop?`<a data-nav href="${urlBranch('/catalogo')}">Productos</a><a data-nav href="${urlBranch('/comparar')}">Comparar</a><a data-nav href="${urlBranch('/cotizar')}">Cotizar lista escolar</a>`:''}</div><div><h4>La Favorita</h4><a data-nav href="/">Nuestras sucursales</a>${app.shop?`<a data-nav href="${urlBranch('/servicios')}">Servicios</a><a data-nav href="${urlBranch('/ofertas')}">Promociones</a>`:''}<a href="${WHATSAPP_LINK}" target="_blank" rel="noopener noreferrer">Contáctanos por WhatsApp</a><a href="/admin/">Panel de administración</a></div><div class="footer-callout"><span class="foot-icon">${icon('heart',24)}</span><strong>Todo para tus compras.</strong><small>Selecciona tu sucursal para ver productos y precios actualizados.</small></div></div><div class="wrap footer-bottom"><span>© ${new Date().getFullYear()} La Favorita · Más que una librería</span><span>Precios y stock de ejemplo hasta cargar el catálogo definitivo.</span></div></footer>`;}
function branchPhoto(b,i){const fallback=`/assets/branches/sucursal-${i+1}.webp`;return `<div class="branch-photo"><img loading="${i<2?'eager':'lazy'}" src="${esc(b.photoUrl||fallback)}" data-fallback="${fallback}" alt="Imagen referencial de la sucursal ${esc(b.name)}"><span class="photo-note">${b.photoUrl?'Foto de la tienda':'Foto ilustrativa'}</span></div>`;}
function branchCard(b,i){return `<a href="/tienda/${encodeURIComponent(b.id)}" data-nav class="branch-card branch-v4" style="--branch:${esc(b.accent||'#ff61b7')};--delay:${i*70}ms"><div class="branch-v4-photo">${branchPhoto(b,i)}<span class="branch-top-index">SUCURSAL ${String(i+1).padStart(2,'0')}</span></div><div class="branch-v4-info"><div class="branch-v4-heading"><div><span class="branch-v4-overline">LA FAVORITA</span><h3>${esc(b.name)}</h3></div><span class="branch-v4-circle">${icon('arrowup',20)}</span></div><div class="branch-v4-facts"><div>${icon('pin',16)}<span>${esc(b.address||'Dirección por confirmar')}</span></div><div>${icon('clock',16)}<span>${esc(b.hours||'Horario por confirmar')}</span></div></div><span class="branch-enter">Ver productos y ofertas ${icon('arrow',18)}</span></div></a>`;}
function gateway(){const branches=app.bootstrap.branches;return `<main class="gateway-v5"><section class="gateway-v5-stage"><div class="wrap"><div class="gateway-v5-intro"><div class="gateway-v5-heading"><span class="gateway-kicker"><span class="pulse-dot"></span> BIENVENIDOS A LA FAVORITA</span><h1>Escoge tu <em>sucursal.</em></h1><p>Encuentra los útiles, materiales y productos que necesitas. Cada tienda tiene sus propios precios y disponibilidad.</p></div><div class="gateway-v5-tiny">${icon('pin',20)} <div><b>Estamos cerca de ti</b><span>Elige dónde deseas comprar</span></div></div></div><div id="sucursales" class="gateway-v5-branches"><div class="gateway-v5-section-title"><div><span class="eyebrow">NUESTRAS TIENDAS</span><h2>¿A cuál vas hoy?</h2></div><span class="gateway-count">${branches.length} sucursales disponibles</span></div><div class="branches-grid branches-v4-grid">${branches.map(branchCard).join('')}</div><div class="gateway-v5-note">${icon('shield',17)} <span>Al ingresar verás los productos y precios de esa sucursal. Las fotografías de los locales son referenciales.</span></div></div></div></section></main>`;}
function sectionTitle(kicker,title,description='',right=''){return `<div class="section-heading"><div><span class="eyebrow">${kicker}</span><h2>${title}</h2>${description?`<p>${description}</p>`:''}</div>${right}</div>`;}
function pill(text,cl=''){return `<span class="small-pill ${cl}">${text}</span>`;}
function cards(items){return `<div class="products-grid">${items.map(productCard).join('')}</div>`;}
function productCard(p){const off=discount(p);return `<article class="product-card product-v4"><a data-nav href="${productUrl(p.id)}" class="product-photo-link" aria-label="Ver ${esc(p.name)}">${picture(p)}${off?`<span class="price-badge">-${off}%</span>`:p.isNew?'<span class="new-badge">NUEVO</span>':''}</a><div class="product-card-body"><div class="brand-line">${esc(p.brand)} <span>· ${esc(categoryName(p.categoryId))}</span></div><a data-nav href="${productUrl(p.id)}" class="product-title">${esc(p.name)}</a><div class="product-card-meta">${esc(p.unitLabel)}${p.unitsPerPack>1?' · x'+p.unitsPerPack:''} ${offerState(p)}</div><div class="product-card-bottom"><div class="price-wrap"><strong>${money(p.price)}</strong>${off?`<del>${money(p.compareAt)}</del>`:''}</div><button type="button" class="round-add" data-action="add" data-id="${esc(p.id)}" aria-label="Añadir ${esc(p.name)} a mi lista" ${p.stock<=0?'disabled':''}>${icon('plus',19)}</button></div><div class="product-v4-actions"><a href="${productUrl(p.id)}" data-nav class="product-v4-detail">Ver detalles ${icon('arrow',15)}</a><a href="${urlBranch('/comparar')}?producto=${encodeURIComponent(p.id)}" data-nav class="product-v4-compare">${icon('compare',16)} Comparar</a></div></div></article>`;}
function liveCampaign(){const campaigns=app.shop.campaigns||[];const c=campaigns[0];return c?{label:c.eyebrow||'CAMPAÑA ESPECIAL',title:c.title,desc:c.description,cta:c.ctaLabel||'Ver productos',category:c.categoryId,badge:c.badge}: {label:'LA FAVORITA · CAMPAÑA PERMANENTE',title:'Pequeños detalles, grandes ideas.',desc:'Descubre la selección de útiles, arte y papelería disponible en tu sucursal.',cta:'Ver colección',category:null,badge:'Inspiración'};}
function storeHero(){const c=liveCampaign(),b=app.shop.branch;return `<section class="store-hero"><div class="wrap"><div class="branch-welcome"><span>${icon('pin',16)} ESTÁS COMPRANDO EN <b>${esc(b.name.toUpperCase())}</b></span><button data-action="switch-branch" class="subtle-link">Cambiar sucursal ${icon('arrow',15)}</button></div><div class="campaign-stage"><div class="campaign-content"><span class="eyebrow light">✦ ${esc(c.label)}</span><h1>${esc(c.title)}</h1><p>${esc(c.desc)}</p><div class="campaign-buttons"><a data-nav href="${urlBranch('/ofertas')}" class="button light">Explorar novedades ${icon('arrow',18)}</a><a data-nav href="${urlBranch('/cotizar')}" class="button outline-white">Cotizar lista ${icon('stars',17)}</a></div></div><img src="/assets/editorial/campaign.svg" alt="Ilustración de útiles escolares" class="campaign-image"><div class="stage-glow"></div></div></div></section>`;}
function categoryTiles(){return `<div class="category-grid">${app.shop.categories.map((c,i)=>`<a data-nav data-reveal class="category-tile category-${i%7}" href="${urlBranch('/categoria/'+encodeURIComponent(c.id))}"><span class="category-symbol">${icon(CATEGORY_ICONS[c.id]||'grid',25)}</span><b>${esc(c.name)}</b><small>${app.shop.products.filter(p=>p.categoryId===c.id).length} productos</small>${icon('arrowup',17)}</a>`).join('')}</div>`;}
function quickTools(){return `<div class="quick-tools"><a data-nav class="quick-tool quick-quote" href="${urlBranch('/cotizar')}"><div class="qt-icon">${icon('stars',27)}</div><div><span class="eyebrow light">COTIZA MÁS RÁPIDO</span><strong>Tu lista escolar, <em>un solo total.</em></strong><small>Escribe tu lista o sube una foto o PDF con IA.</small><span class="qt-link">Cotizar ahora ${icon('arrow',16)}</span></div><span class="qt-orb"></span></a><a data-nav class="quick-tool quick-compare" href="${urlBranch('/comparar')}"><div class="qt-icon">${icon('compare',27)}</div><div><span class="eyebrow light">ELIGE CON CONFIANZA</span><strong>Compara tus <em>opciones.</em></strong><small>Precios, características y opciones equivalentes.</small><span class="qt-link">Abrir comparador ${icon('arrow',16)}</span></div></a></div>`;}
function storefront(){const products=app.shop.products.filter(p=>p.price>0);const selected={beneficios:()=>`<section class="wrap section service-overview">${sectionTitle('TE LO PONEMOS FÁCIL','Más soluciones, <em>menos complicaciones.</em>')}<div class="service-overview-grid"><div>${icon('printer',22)}<b>Copias e impresiones</b><small>Para tareas y proyectos</small></div><div>${icon('book',22)}<b>Útiles escolares</b><small>Todo para cada curso</small></div><div>${icon('palette',22)}<b>Arte y creatividad</b><small>Un mundo de color</small></div><div>${icon('gift',22)}<b>Campañas especiales</b><small>Temporadas para celebrar</small></div></div></section>`,categorias:()=>`<section class="wrap section">${sectionTitle('EXPLORA A TU MANERA','¿Qué necesitas <em>hoy?</em>','Encuentra rápido el tipo de artículo que estás buscando.',`<a class="text-link" data-nav href="${urlBranch('/catalogo')}">Ver todos ${icon('arrow',17)}</a>`)}${categoryTiles()}</section>`,destacados:()=>`<section class="wrap section">${sectionTitle('NUESTROS FAVORITOS','Los más buscados <em>por aquí.</em>','Una selección para empezar.',`<a class="text-link" data-nav href="${urlBranch('/catalogo')}">Ir al catálogo ${icon('arrow',17)}</a>`)}${cards(products.filter(p=>p.featured).slice(0,8).length?products.filter(p=>p.featured).slice(0,8):products.slice(0,8))}</section>`,novedades:()=>`<section class="wrap section">${sectionTitle('RECIÉN LLEGADOS','Un poquito de <em>novedad.</em>','Ideas nuevas para tu día a día.',`<a class="text-link" data-nav href="${urlBranch('/novedades')}">Ver novedades ${icon('arrow',17)}</a>`)}${cards(products.filter(p=>p.isNew).slice(0,4).length?products.filter(p=>p.isNew).slice(0,4):products.slice(8,12))}</section>`,catalogo:()=>`<section class="wrap section preview-catalog">${sectionTitle('UN CATÁLOGO PARA TI','Encuentra tu próximo <em>favorito.</em>','No te quedes solo con estas opciones: tenemos mucho más.',`<a class="button secondary" data-nav href="${urlBranch('/catalogo')}">Explorar catálogo ${icon('arrow',17)}</a>`)}${cards(products.slice(12,16))}</section>`};
const arranged=app.shop.sections.map(s=>s.id).filter(k=>selected[k]);return `<main>${storeHero()}<div class="wrap shop-intro-line"><div><span class="hello-dot"></span> Precios y existencias de <b>${esc(app.shop.branch.name)}</b></div><span>${app.shop.products.length} referencias en esta sucursal</span></div><div class="wrap" style="margin-top:23px">${quickTools()}</div>${arranged.map(k=>selected[k]()).join('')}<section class="wrap newsletter-belt"><div><span class="eyebrow light">¿LISTA ESCOLAR EN MANO?</span><h2>Deja de sumar uno por uno.</h2><p>Te mostramos un único importe para tu lista.</p></div><a data-nav class="button light" href="${urlBranch('/cotizar')}">Probar cotizador ${icon('arrow',17)}</a></section></main>`;}
function pageBanner(kicker,title,subtitle='',color='blue'){return `<section class="page-banner banner-${color}"><div class="wrap"><div class="breadcrumbs"><a data-nav href="/">Inicio</a><span>›</span><a data-nav href="${urlBranch()}">${esc(app.shop.branch.name)}</a><span>›</span><span>${esc(kicker)}</span></div><div class="page-banner-body"><div><span class="eyebrow light">${kicker}</span><h1>${title}</h1><p>${subtitle}</p></div><div class="page-sparkle" aria-hidden="true">✦<i>✧</i></div></div></div></section>`;}
function catalogueProducts(){let xs=app.shop.products.filter(x=>x.price>0);const q=fold(app.query);if(q){const words=q.split(' ').filter(Boolean);xs=xs.map(p=>{const hay=fold([p.name,p.brand,p.categoryId,p.subCategory,p.model,p.description,p.sku,p.searchAliases,p.usage].join(' '));const matched=words.filter(x=>hay.includes(x)).length;return {...p,_score:hay.includes(q)?100+matched:matched===words.length?30+matched*3:matched>=2?matched:0};}).filter(p=>p._score>0);}
if(app.category!=='all')xs=xs.filter(p=>p.categoryId===app.category);if(app.brand!=='all')xs=xs.filter(p=>p.brand===app.brand);if(app.stockOnly)xs=xs.filter(p=>p.stock>0);if(app.order==='low')xs.sort((a,b)=>a.price-b.price);else if(app.order==='high')xs.sort((a,b)=>b.price-a.price);else if(app.order==='az')xs.sort((a,b)=>a.name.localeCompare(b.name,'es'));else if(app.order==='new')xs.sort((a,b)=>Number(b.isNew)-Number(a.isNew));else if(q)xs.sort((a,b)=>b._score-a._score);return xs;}
function catalogCount(){return catalogueProducts().length;}
function suggestionsHtml(){const q=fold(app.query);if(q.length<2)return '';const picks=app.shop.products.filter(p=>fold(p.name+' '+p.brand).includes(q)).slice(0,5);return picks.length?`<div class="search-suggestions">${picks.map(p=>`<a data-nav href="${productUrl(p.id)}">${icon('search',14)} <span>${esc(p.name)}</span><small>${money(p.price)}</small></a>`).join('')}</div>`:'';}
function catalogueGrid(){const items=catalogueProducts();return `<div class="catalog-count"><span>Mostrando <b>${items.length}</b> producto${items.length===1?'':'s'}</span><span>${esc(app.shop.branch.name)}</span></div>${items.length?cards(items):`<div class="search-empty">${icon('search',38)}<h3>No encontramos productos con esos filtros.</h3><p>Prueba buscando otra marca, producto o presentación.</p><button class="button secondary" data-action="clear-filters">Ver todos los artículos</button></div>`}`;}
function catalogue(){const brands=[...new Set(app.shop.products.map(p=>p.brand))].sort((a,b)=>a.localeCompare(b,'es'));return `<main>${pageBanner('CATÁLOGO','Encuentra lo que <em>necesitas.</em>','Busca útiles, consulta precios y compara opciones en esta sucursal.','pink')}<div class="wrap catalogue-layout"><aside class="filter-sidebar"><div class="filter-title">${icon('filter',20)} <b>Filtrar productos</b><button data-action="clear-filters">Limpiar</button></div><div class="filter-block"><strong>Categorías</strong><div class="filter-options"><button class="filter-category ${app.category==='all'?'active':''}" data-action="cat" data-category="all">Todo el catálogo <span>${app.shop.products.length}</span></button>${app.shop.categories.map(c=>`<button class="filter-category ${app.category===c.id?'active':''}" data-action="cat" data-category="${esc(c.id)}">${esc(c.name)}<span>${app.shop.products.filter(p=>p.categoryId===c.id).length}</span></button>`).join('')}</div></div><div class="filter-block"><label for="brand-select"><strong>Marca</strong></label><select id="brand-select"><option value="all">Todas las marcas</option>${brands.map(b=>`<option ${b===app.brand?'selected':''} value="${esc(b)}">${esc(b)}</option>`).join('')}</select></div><div class="filter-block"><label class="check-filter"><input id="available-filter" type="checkbox" ${app.stockOnly?'checked':''}> Solo con stock</label></div><div class="filter-bottom-info">${icon('shield',20)} Precios y stock de la sucursal seleccionada.</div></aside><div class="catalog-main"><div class="catalogue-toolbar"><div class="search-zone"><label class="catalogue-search">${icon('search',21)} <input id="catalog-search" type="search" value="${esc(app.query)}" placeholder="Busca lápices, plumones x12, silicona..." autocomplete="off" aria-label="Buscar productos"></label><div id="catalog-suggestions">${suggestionsHtml()}</div></div><label class="order-wrap">Ordenar <select id="order-select"><option value="relevancia" ${app.order==='relevancia'?'selected':''}>Relevancia</option><option value="low" ${app.order==='low'?'selected':''}>Menor precio</option><option value="high" ${app.order==='high'?'selected':''}>Mayor precio</option><option value="new" ${app.order==='new'?'selected':''}>Novedades</option><option value="az" ${app.order==='az'?'selected':''}>A a Z</option></select></label></div><div class="mobile-category-chips"><button data-action="cat" data-category="all" class="${app.category==='all'?'active':''}">Todos</button>${app.shop.categories.map(c=>`<button data-action="cat" data-category="${esc(c.id)}" class="${app.category===c.id?'active':''}">${esc(c.name)}</button>`).join('')}</div><div class="mobile-filter-row"><label>Marca <select id="mobile-brand"><option value="all">Todas</option>${brands.map(b=>`<option value="${esc(b)}" ${app.brand===b?'selected':''}>${esc(b)}</option>`).join('')}</select></label><label class="check-filter"><input id="mobile-stock" type="checkbox" ${app.stockOnly?'checked':''}> Disponibles</label></div><div id="catalog-results">${catalogueGrid()}</div></div></div></main>`;}
function campaignProducts(which){let xs=app.shop.products.filter(p=>p.price>0);if(which==='ofertas')xs=xs.filter(p=>discount(p)>0);else xs=xs.filter(p=>p.isNew);return xs;}
function collection(which){const isOffers=which==='ofertas',products=campaignProducts(which);return `<main>${pageBanner(isOffers?'PROMOCIONES':'NOVEDADES',isOffers?'Tus favoritos con <em>algo extra.</em>':'Acaban de llegar <em>cosas bonitas.</em>',isOffers?'Descubre los productos con descuentos configurados para tu tienda.':'Un espacio para encontrar lo nuevo que va llegando.','pink')}<section class="wrap section">${sectionTitle(isOffers?'OFERTAS DE LA SUCURSAL':'LO MÁS RECIENTE',isOffers?'Descubre las <em>promociones.</em>':'Llegaron nuevas <em>ideas.</em>')}${products.length?cards(products):`<div class="search-empty"><h3>No hay promociones activas en esta sucursal por ahora.</h3><p>Desde administración se pueden configurar descuentos y novedades en cualquier momento.</p><a data-nav class="button secondary" href="${urlBranch('/catalogo')}">Explorar catálogo</a></div>`}</section></main>`;}
function compareGroups(){const groups=new Map();for(const p of app.shop.products){if(!p.comparisonGroup||p.price<=0||p.stock<=0)continue;let g=groups.get(p.comparisonGroup);if(!g){g={id:p.comparisonGroup,title:p.comparisonLabel||p.comparisonGroup,products:[]};groups.set(p.comparisonGroup,g);}g.products.push(p);}return [...groups.values()].filter(g=>g.products.length>=2).sort((a,b)=>a.title.localeCompare(b.title,'es'));}
function comparePage(){const groups=compareGroups();const selectedProduct=app.shop.products.find(p=>p.id===app.compareProduct);if(selectedProduct?.comparisonGroup && groups.some(g=>g.id===selectedProduct.comparisonGroup))app.compareGroup=selectedProduct.comparisonGroup;if(!groups.some(g=>g.id===app.compareGroup))app.compareGroup=groups[0]?.id||'';const group=groups.find(g=>g.id===app.compareGroup);const noMatches=selectedProduct&&(!selectedProduct.comparisonGroup||!groups.some(g=>g.id===selectedProduct.comparisonGroup));const xs=(noMatches?[]:(group?.products||[])).slice().sort((a,b)=>a.price-b.price);return `<main>${pageBanner('COMPARADOR','Compara tus <em>opciones.</em>',`Alternativas y precios disponibles solamente en ${esc(app.shop.branch.name)}.`,'blue')}<section class="wrap section compare-page"><div class="compare-location-note">${icon('pin',17)} Comparación exclusiva de <strong>${esc(app.shop.branch.name)}</strong>. No mostramos precios de otras sucursales.</div><div class="compare-intro"><div>${sectionTitle('PRECIOS DE TU SUCURSAL','Elige la opción <em>que necesitas.</em>','Compara productos del mismo tipo y presentación, aunque sean de distintas marcas o modelos.')}</div><div class="compare-select"><label for="compare-group">¿Qué vas a comparar?</label><select id="compare-group">${groups.map(g=>`<option value="${esc(g.id)}" ${app.compareGroup===g.id?'selected':''}>${esc(g.title)} · ${g.products.length} opciones</option>`).join('')}</select></div></div>${!xs.length?`<div class="search-empty"><h3>${noMatches?`Aún no hay alternativas para ${esc(selectedProduct.name)}.`:"Todavía no hay opciones para comparar."}</h3><p>Solo aparecerán productos equivalentes con precio y disponibilidad en esta tienda. Puedes elegir otro grupo en el selector.</p></div>`:`<div class="compare-table-wrap"><table class="compare-table"><thead><tr><th>Características</th>${xs.map((p,i)=>`<th class="${i===0?'winner':''}">${i===0?'<span class="comparison-winner">MENOR PRECIO</span>':''}<a data-nav href="${productUrl(p.id)}">${picture(p,'mini-picture')}</a><strong>${esc(p.name)}</strong><small>${esc(p.brand)}</small></th>`).join('')}</tr></thead><tbody><tr><th>Precio en ${esc(app.shop.branch.name)}</th>${xs.map((p,i)=>`<td class="${i===0?'winner':''}"><strong class="compare-price">${money(p.price)}</strong></td>`).join('')}</tr><tr><th>Marca</th>${xs.map(p=>`<td>${esc(p.brand)}</td>`).join('')}</tr><tr><th>Presentación</th>${xs.map(p=>`<td>${esc(p.unitLabel)}${p.unitsPerPack>1?' x'+p.unitsPerPack:''}</td>`).join('')}</tr><tr><th>Modelo</th>${xs.map(p=>`<td>${esc(p.model||'No registrado')}</td>`).join('')}</tr><tr><th>Uso</th>${xs.map(p=>`<td>${esc(p.usage||'Consultar ficha')}</td>`).join('')}</tr><tr><th>Disponibilidad</th>${xs.map(p=>`<td>${offerState(p)}</td>`).join('')}</tr><tr><th>Ver producto</th>${xs.map(p=>`<td><a data-nav class="tiny-cta" href="${productUrl(p.id)}">Ver ficha ${icon('arrow',15)}</a></td>`).join('')}</tr></tbody></table></div>`}<div class="disclaimer-box">${icon('shield',21)} <span>Estos precios corresponden a esta sucursal. Para una comparación justa, cada grupo reúne artículos de uso y presentación equivalentes.</span></div></section></main>`;}
function detailsPage(id){const p=app.shop.products.find(x=>x.id===id);if(!p)return `<main class="wrap section"><h1>No encontramos ese producto.</h1><a data-nav href="${urlBranch('/catalogo')}" class="button primary">Volver al catálogo</a></main>`;const similar=app.shop.products.filter(x=>x.id!==p.id&&x.comparisonGroup&&x.comparisonGroup===p.comparisonGroup&&x.stock>0).slice(0,4);const off=discount(p);return `<main><div class="wrap detail-breadcrumb"><a data-nav href="${urlBranch()}">Mi tienda</a><span>›</span><a data-nav href="${urlBranch('/categoria/'+p.categoryId)}">${esc(categoryName(p.categoryId))}</a><span>›</span><span>${esc(p.name)}</span></div><div class="wrap detail-grid"><div class="detail-gallery">${picture(p,'large-picture')}<div class="gallery-message">${icon('shield',16)} Imagen orientativa si aún no se cargó la fotografía oficial.</div></div><div class="detail-info"><span class="eyebrow">${esc(p.brand)} · ${esc(p.sku)}</span><h1>${esc(p.name)}</h1><div class="detail-subtitle">${esc(p.model||'Modelo por confirmar')} · ${esc(categoryName(p.categoryId))}</div><div class="detail-tags">${p.isNew?pill('Novedad','new'):''}${off?pill(`Descuento ${off}%`,'discount'):''}${pill('Precio por sucursal','')}</div><div class="detail-main-price">${money(p.price)} ${off?`<del>${money(p.compareAt)}</del>`:''}</div><div class="detail-stock-label">${offerState(p)} en <b>${esc(app.shop.branch.name)}</b></div><p class="detail-description">${esc(p.description||'Una opción para tus tareas, materiales y proyectos del día a día.')}</p><div class="detail-facts"><div><span>Presentación</span><b>${esc(p.unitLabel)}${p.unitsPerPack>1?' x'+p.unitsPerPack:''}</b></div><div><span>Contenido</span><b>${p.netContent?`${p.netContent} ${esc(p.netUnit)}`:'No especificado'}</b></div><div><span>Uso principal</span><b>${esc(p.usage||'Por definir')}</b></div></div><div class="detail-actions"><button class="button primary" data-action="add" data-id="${esc(p.id)}" ${p.stock<=0?'disabled':''}>${icon('bag',19)} Añadir a mi lista</button><a data-nav href="${urlBranch('/comparar')}?producto=${encodeURIComponent(p.id)}" class="button secondary">${icon('compare',18)} Comparar</a></div></div></div><div class="wrap details-under"><section class="info-panel"><h2>Características y detalles</h2><div class="feature-row"><span>Marca</span><b>${esc(p.brand)}</b></div><div class="feature-row"><span>Modelo</span><b>${esc(p.model||'Sin especificar')}</b></div><div class="feature-row"><span>Presentación</span><b>${esc(p.unitLabel)}</b></div><div class="feature-row"><span>Características</span><b>${esc(p.features||'Pendiente de información específica del fabricante')}</b></div></section><section class="info-panel"><h2>Encuéntralo en tu sucursal</h2><p>Estás viendo el precio y el stock de <b>${esc(app.shop.branch.name)}</b>. Si buscas otras marcas o modelos, utiliza el comparador de esta misma tienda.</p><div class="detail-branch-info">${icon('pin',22)}<div><b>${esc(app.shop.branch.name)}</b><small>${esc(app.shop.branch.address||'Dirección por confirmar')}</small><small>${esc(app.shop.branch.hours||'Horario por confirmar')}</small></div></div><a data-nav class="button secondary" href="${urlBranch('/comparar')}?producto=${encodeURIComponent(p.id)}">${icon('compare',17)} Comparar opciones aquí</a></section></div>${similar.length?`<section class="wrap section">${sectionTitle('OPCIONES DE ESTA SUCURSAL','Quizá también te <em>interesen.</em>','Otras marcas y modelos disponibles aquí.')}${cards(similar)}</section>`:''}</main>`;}
function quotePage(){return `<main>${pageBanner('COTIZACIÓN ESCOLAR','Tu lista, <em>sin complicaciones.</em>','Un único precio final según tu preferencia. Cuando algo falte, te lo diremos claramente.','purple')}<div class="wrap quote-main"><div class="quote-step-head"><span class="ai-chip">${icon('stars',16)} COTIZADOR ESCOLAR</span><h2>¡Deja que nosotros hagamos las cuentas!</h2><p>Trabajamos con los precios disponibles de <b>${esc(app.shop.branch.name)}</b>. Escribe tu lista y calcula un total de ejemplo. Las fotos y PDF requieren activar la lectura automática.</p></div><div class="quote-layout"><form class="quote-form" id="quote-form"><div class="form-section"><div class="form-step-title"><span>01</span><div><h3>Elige cómo quieres tu cotización</h3><small>Seleccionaremos artículos compatibles según su precio y clasificación.</small></div></div><div class="quote-tiers">${[['economica','Económica','Ahorra al máximo','💚'],['equilibrada','Equilibrada','Un punto medio ideal','💜'],['calidad','Calidad prioritaria','Preferencia por productos mejor clasificados','✨']].map(([val,name,desc,emoji])=>`<label class="quote-tier ${app.quoteTier===val?'selected':''}"><input type="radio" name="tier" value="${val}" ${app.quoteTier===val?'checked':''}><span class="tier-emoji">${emoji}</span><b>${name}</b><small>${desc}</small><span class="radio-dot"></span></label>`).join('')}</div></div><div class="form-section"><div class="form-step-title"><span>02</span><div><h3>Escribe o adjunta tu lista</h3><small>Sirve una lista corta o una lista escolar completa.</small></div></div><textarea id="school-text" class="quote-textarea" rows="7" placeholder="Ejemplo:\n2 Lapicero BP-S azul\n1 Cuaderno A4 rayado 100 hojas\n1 Plumones Fiesta x12"></textarea><div class="file-upload-wrap"><input id="school-file" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp,application/pdf,image/*"><label for="school-file" class="file-upload">${icon('upload',25)}<span><b>O sube una foto / PDF</b><small id="file-name">JPG, PNG, WebP o PDF · máximo 8 MB</small></span>${icon('arrow',18)}</label></div><div class="ai-status-line" id="ai-status">${icon('stars',16)} Comprobando conexión de IA...</div></div><div class="form-submit"><button class="button primary wide" type="submit" id="quote-submit">${icon('stars',19)} Obtener cotización</button><button class="button secondary wide" type="button" data-action="quote-demo">${icon('play',17)} Probar con lista de ejemplo</button></div><p class="fineprint">Los precios son referenciales. Para leer fotografías y PDF, primero debe habilitarse la lectura automática.</p></form><aside class="quote-output" id="quote-output"><div class="quote-output-top"><span class="eyebrow light">✦ TU RESULTADO</span>${icon('stars',32)}</div><div class="quote-result-placeholder"><div class="result-orb">${icon('file',42)}</div><h3>Tu cotización aparecerá aquí.</h3><p>Te daremos <b>un único precio</b>, sin mostrar los precios individuales. Si algo no se reconoce, lo indicaremos debajo.</p></div><div class="output-points"><div>${icon('check',17)} Sin precios por artículo</div><div>${icon('check',17)} Tres niveles de cotización</div><div>${icon('check',17)} Avisos de artículos faltantes</div></div></aside></div></div><section class="wrap how-quote">${sectionTitle('PENSADO PARA TUS LISTAS','Así de <em>fácil.</em>')}<div class="how-quote-grid"><div><span>1</span><b>Elige tu modalidad</b><p>Económica, equilibrada o calidad prioritaria.</p></div><div><span>2</span><b>Compararemos opciones</b><p>Solo productos disponibles y compatibles.</p></div><div><span>3</span><b>Recibe un único total</b><p>Y observa qué artículos necesitan revisión.</p></div></div></section></main>`;}
function quoteResultHTML(r){const issues=[...(r.unrecognized||[]).map(x=>({name:x,why:'Texto no entendible'})),...(r.missing||[]).map(x=>({name:x,why:'No encontrado o sin stock'}))];return `<div class="quote-output-top"><span class="eyebrow light">✦ RESULTADO DE TU LISTA</span>${icon('check',27)}</div><div class="quote-result-value"><span>${r.complete?'PRECIO TOTAL DE LA COTIZACIÓN':'SUBTOTAL DE LOS ARTÍCULOS ENCONTRADOS'}</span><strong>${money(r.total)}</strong><small>${r.includedCount} de ${r.totalCount} artículos incluidos · ${r.tier==='economica'?'Económica':r.tier==='equilibrada'?'Equilibrada':'Calidad prioritaria'}</small></div>${issues.length?`<div class="quote-alert">${icon('alert',22)} <div><strong>Tu lista necesita revisión.</strong><p>El importe no incluye los siguientes artículos:</p></div></div><div class="quote-issues">${issues.map(o=>`<div><b>${esc(o.name)}</b><small>${esc(o.why)}</small></div>`).join('')}</div>`:`<div class="quote-complete">${icon('check',18)} Todos los artículos de la lista fueron incluidos.</div>`}<p class="result-notice">Precios referenciales, sujetos a confirmación y disponibilidad. No se reserva mercadería.</p><button class="button light wide" data-action="quote-reset" type="button">Cotizar otra lista ${icon('arrow',17)}</button>`;}
function services(){return `<main>${pageBanner('SERVICIOS','Más que productos, <em>soluciones.</em>','Para el colegio, la oficina, tus ideas y tus proyectos.','blue')}<section class="wrap section">${sectionTitle('TAMBIÉN PODEMOS AYUDARTE','Todo lo que necesitas <em>en un solo lugar.</em>')}<div class="services-grid">${[['printer','Copias e impresiones','Apoyo para tareas, apuntes y documentos.'],['book','Útiles escolares','Cuadernos, lápices, colores y todos esos pequeños imprescindibles.'],['palette','Arte y manualidades','Materiales para darle forma a tus ideas.'],['file','Anillados y enmicados','Acabados prácticos para documentos y proyectos.'],['gift','Campañas de temporada','Detalles para fechas especiales y celebraciones.'],['stars','Cotizaciones escolares','Una sola cifra para tu lista, por modalidad.']].map(([ic,title,sub])=>`<article class="service-card">${icon(ic,27)}<h3>${title}</h3><p>${sub}</p></article>`).join('')}</div></section></main>`;}
function appPage(){if(!app.shop)return gateway();switch(app.route.page){case 'catalogo':case 'categoria':return catalogue();case 'comparar':return comparePage();case 'cotizar':return quotePage();case 'producto':return detailsPage(app.route.id);case 'ofertas':return collection('ofertas');case 'novedades':return collection('novedades');case 'servicios':return services();default:return storefront();}}
function breadcrumbTitle(){return app.route?.page==='producto'?app.shop?.products.find(p=>p.id===app.route.id)?.name:({catalogo:'Catálogo',comparar:'Comparador',cotizar:'Cotizador escolar',ofertas:'Promociones',novedades:'Novedades',servicios:'Servicios'})[app.route?.page]||app.shop?.branch?.name||'Inicio';}
function render(){document.documentElement.style.setProperty('--accent-pink',app.bootstrap.settings.primaryColor||'#f026ad');document.documentElement.style.setProperty('--accent-teal',app.bootstrap.settings.secondaryColor||'#26c4e7');$('#app').innerHTML=header()+appPage()+footer()+whatsappFloat()+'<div id="overlay-root"></div><div id="toast-root" aria-live="polite"></div>';document.title=`${breadcrumbTitle()} | La Favorita`;const live=app.shop&&app.shop.settings.showProvisionalNotice;if(live)$('.site-header')?.insertAdjacentHTML('afterend','<div class="provisional-alert">Catálogo de prueba: precios y existencias referenciales hasta completar la información de la tienda.</div>');reveal();}
function parseRoute(path){const found=path.match(/^\/tienda\/([^/]+)(?:\/(.*))?$/);if(!found)return {page:'gateway',branch:null};const rem=found[2]||'';const [page,id]=rem.split('/');return {page:page||'home',id:decodeURIComponent(id||''),branch:decodeURIComponent(found[1])};}
async function navigate(path,{replace=false,scroll=true}={}){try{const target=new URL(path,location.origin);if(target.origin!==location.origin){location.href=path;return;}const route=parseRoute(target.pathname);if(route.page==='categoria'){app.category=route.id;route.page='catalogo';}else if(route.page!=='catalogo'){app.category='all';app.brand='all';app.query='';app.order='relevancia';app.stockOnly=false;}if(route.page==='comparar'){app.compareProduct=target.searchParams.get('producto')||'';app.compareGroup=target.searchParams.get('grupo')||'';}if(route.page==='catalogo'&&target.searchParams.get('q'))app.query=target.searchParams.get('q');if(!app.bootstrap)app.bootstrap=await api('/api/bootstrap');if(route.branch){if(!app.shop||app.shop.branch.id!==route.branch){app.shop=await api(`/api/store/${encodeURIComponent(route.branch)}`);app.branchId=route.branch;readCart();}else if(Date.now()-app.loadedAt>15000){app.shop=await api(`/api/store/${encodeURIComponent(route.branch)}`);}}else{app.shop=null;app.branchId=null;app.cart=[];}app.route=route;app.menu=false;app.cartOpen=false;app.loadedAt=Date.now();if(location.pathname+location.search!==target.pathname+target.search){history[replace?'replaceState':'pushState'](null,'',target.pathname+target.search);}render();if(route.page==='cotizar'){loadAIStatus();if(target.searchParams.get('demo')==='1'){fillSample();}}if(scroll)window.scrollTo({top:0,behavior:'instant'});}
catch(e){$('#app').innerHTML=`<div class="error-screen"><h1>No pudimos abrir la tienda</h1><p>${esc(e.message)}</p><a href="/" class="button primary">Volver al inicio</a></div>`;console.error(e);}}
async function loadAIStatus(){try{app.aiStatus=await api('/api/ai/status');const el=$('#ai-status');if(el)el.innerHTML=app.aiStatus.configured?`${icon('check',17)} Lectura automática de fotos y PDF habilitada.`:`${icon('shield',17)} Simulación por texto disponible · Para interpretar imágenes y PDF conecta la API de IA.`;}catch{}}
function fillSample(){const el=$('#school-text');if(!el)return;el.value=SAMPLE_LIST;const f=$('#school-file');if(f)f.value='';const name=$('#file-name');if(name)name.textContent='JPG, PNG, WebP o PDF · máximo 8 MB';toast('Lista de ejemplo cargada. Puedes calcularla ahora.');}
async function requestQuote(){const textarea=$('#school-text');const file=$('#school-file')?.files[0];const text=textarea?.value?.trim()||'';if(!text&&!file)throw Error('Escribe una lista o adjunta un archivo.');if(file&&file.size>8*1024*1024)throw Error('El archivo supera los 8 MB.');const payload={branchId:app.branchId,tier:app.quoteTier};if(file){if(!app.aiStatus?.configured)throw Error('La lectura de foto/PDF aún no está activada. Puedes probar la cotización escribiendo una lista o usando el ejemplo.');const mimeType=file.type||({'pdf':'application/pdf','png':'image/png','jpg':'image/jpeg','jpeg':'image/jpeg','webp':'image/webp'}[file.name.split('.').pop().toLowerCase()]);if(!['application/pdf','image/png','image/jpeg','image/webp'].includes(mimeType))throw Error('Formato no permitido.');const data=await new Promise((ok,fail)=>{const reader=new FileReader();reader.onload=()=>ok(reader.result);reader.onerror=fail;reader.readAsDataURL(file);});payload.file={filename:file.name,mimeType,base64:String(data).split(',')[1]};}else payload.text=text;return api('/api/school-quote',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});}
async function submitQuote(){const el=$('#quote-output'),button=$('#quote-submit');if(button)button.disabled=true;el.innerHTML=`<div class="loading-quote"><div class="spinner"></div><h3>Revisando tu lista...</h3><p>Comprobando productos, opciones y precios de esta sucursal.</p></div>`;try{const result=await requestQuote();el.innerHTML=quoteResultHTML(result);app.quoteResult=result;el.scrollIntoView({behavior:'smooth',block:'nearest'});}catch(e){el.innerHTML=`<div class="quote-result-placeholder"><div class="result-orb">${icon('alert',37)}</div><h3>No se pudo calcular todavía</h3><p>${esc(e.message)}</p><button type="button" class="button light" data-action="quote-demo">Probar con lista de ejemplo</button></div>`;}finally{if(button)button.disabled=false;}}
function addCart(id){const product=app.shop?.products.find(p=>p.id===id);if(!product||product.stock<=0)return toast('Este producto no tiene stock disponible.');let item=app.cart.find(x=>x.id===id);if(!item){item={id,qty:0};app.cart.push(item);}item.qty=Math.min(product.stock,item.qty+1);writeCart();const count=$('.cart-count');if(count)count.textContent=cartCount();toast('¡Agregado a tu lista!');}
function cartContents(){let total=0;const items=app.cart.map(x=>{const p=app.shop?.products.find(p=>p.id===x.id);if(!p)return '';total+=p.price*x.qty;return `<div class="cart-item">${picture(p,'cart-product-image')}<div><b>${esc(p.name)}</b><small>${money(p.price)} · ${esc(p.brand)}</small><div class="qty-edit"><button data-action="qty" data-id="${esc(p.id)}" data-step="-1">−</button><strong>${x.qty}</strong><button data-action="qty" data-id="${esc(p.id)}" data-step="1">+</button></div></div><button data-action="remove" data-id="${esc(p.id)}" class="cart-remove">${icon('close',17)}</button></div>`;}).join('');return {items,total};}
function openCart(){if(!app.shop)return;app.cartOpen=true;const {items,total}=cartContents();$('#overlay-root').innerHTML=`<div class="drawer-backdrop" data-action="close-cart"><aside class="cart-drawer" role="dialog" aria-modal="true" aria-label="Mi lista de productos"><header class="drawer-heading"><div><span class="eyebrow">MI LISTA DE COMPRA</span><h2>Mis favoritos <em>para llevar.</em></h2></div><button class="icon-button" data-action="close-cart" aria-label="Cerrar lista">${icon('close',22)}</button></header><div class="drawer-items">${items||`<div class="cart-empty">${icon('bag',44)}<h3>Tu lista está esperando.</h3><p>Agrega productos para preparar una consulta de tu sucursal.</p></div>`}</div><div class="cart-drawer-bottom"><div><span>Total referencial</span><b>${money(total)}</b></div><button class="button primary wide" data-action="copy-cart" ${!app.cart.length?'disabled':''}>${icon('copy',17)} Copiar lista</button><small>No procesamos pagos ni reservas desde esta sección.</small></div></aside></div>`;document.body.classList.add('lock-scroll');}
function closeCart(){app.cartOpen=false;$('#overlay-root').innerHTML='';document.body.classList.remove('lock-scroll');}
function changeQty(id,step){const it=app.cart.find(i=>i.id===id),p=app.shop?.products.find(p=>p.id===id);if(!it||!p)return;it.qty=Math.max(0,Math.min(p.stock,it.qty+step));if(it.qty===0)app.cart=app.cart.filter(x=>x.id!==id);writeCart();const badge=$('.cart-count');if(badge)badge.textContent=cartCount();openCart();}
async function copyCart(){const {total}=cartContents();const lines=app.cart.map(x=>{const p=app.shop.products.find(p=>p.id===x.id);return p?`${x.qty} × ${p.name} (${p.brand}) — ${money(p.price*x.qty)}`:'';}).filter(Boolean);const s=`LA FAVORITA — Consulta de productos\nSucursal: ${app.shop.branch.name}\n\n${lines.join('\n')}\n\nTotal referencial: ${money(total)}\nPrecios a confirmar en tienda.`;try{await navigator.clipboard.writeText(s);toast('¡Lista copiada! Ya puedes compartirla.');}catch{const ta=document.createElement('textarea');ta.value=s;document.body.append(ta);ta.select();document.execCommand('copy');ta.remove();toast('Lista copiada.');}}
function toast(message){let t=$('#toast-root');if(!t)return;t.innerHTML=`<div class="toast-message">${icon('check',18)} ${esc(message)}</div>`;clearTimeout(app.toastTimer);app.toastTimer=setTimeout(()=>{if(t)t.innerHTML='';},3400);}
function reveal(){const els=$$('[data-reveal]');if(!('IntersectionObserver'in window)||matchMedia('(prefers-reduced-motion: reduce)').matches){els.forEach(e=>e.classList.add('visible'));return;}const io=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target);}},{threshold:.08});els.forEach(el=>io.observe(el));}
function refreshCatalog(){const result=$('#catalog-results');if(result){result.innerHTML=catalogueGrid();reveal();}}
document.addEventListener('click',async event=>{
 const a=event.target.closest('a[data-nav]');if(a && !event.ctrlKey&&!event.metaKey&&!event.shiftKey&&event.button===0){event.preventDefault();await navigate(a.href);return;}
 const btn=event.target.closest('[data-action]');if(!btn)return;const action=btn.dataset.action;
 if(action==='toggle-menu'){app.menu=!app.menu;render();return;}
 if(action==='switch-branch'){const menu=$('#branch-switch-menu');const trigger=$('#branch-switch-btn');if(!menu||!trigger)return;const wasHidden=menu.hidden;menu.hidden=!wasHidden;trigger.setAttribute('aria-expanded',String(wasHidden));if(wasHidden)trigger.focus({preventScroll:true});return;}
 if(action==='add'){addCart(btn.dataset.id);return;}
 if(action==='cart'){openCart();return;}
 if(action==='close-cart'){if(btn===event.target||btn.closest('.drawer-heading'))closeCart();return;}
 if(action==='remove'){app.cart=app.cart.filter(x=>x.id!==btn.dataset.id);writeCart();openCart();return;}
 if(action==='qty'){changeQty(btn.dataset.id,Number(btn.dataset.step));return;}
 if(action==='copy-cart'){await copyCart();return;}
 if(action==='cat'){app.category=btn.dataset.category;$$('[data-action="cat"]').forEach(x=>x.classList.toggle('active',x.dataset.category===app.category));refreshCatalog();return;}
 if(action==='clear-filters'){app.query='';app.category='all';app.brand='all';app.order='relevancia';app.stockOnly=false;render();return;}
 if(action==='quote-demo'){fillSample();if(btn.closest('#quote-output')){const output=$('#quote-output');output.innerHTML=`<div class="quote-output-top"><span class="eyebrow light">✦ TU RESULTADO</span>${icon('stars',32)}</div><div class="quote-result-placeholder"><h3>Lista de ejemplo cargada</h3><p>Presiona «Obtener cotización» para calcular el total usando los precios de esta sucursal.</p></div>`;}return;}
 if(action==='quote-reset'){app.quoteResult=null;await navigate(urlBranch('/cotizar'));return;}
});
document.addEventListener('input',e=>{if(e.target.id==='catalog-search'){app.query=e.target.value;refreshCatalog();const el=$('#catalog-suggestions');if(el)el.innerHTML=suggestionsHtml();}});
document.addEventListener('change',e=>{if(e.target.id==='brand-select'||e.target.id==='mobile-brand'){app.brand=e.target.value;refreshCatalog();}if(e.target.id==='available-filter'||e.target.id==='mobile-stock'){app.stockOnly=e.target.checked;refreshCatalog();}if(e.target.id==='order-select'){app.order=e.target.value;refreshCatalog();}if(e.target.id==='compare-group'){app.compareProduct='';app.compareGroup=e.target.value;render();}if(e.target.name==='tier'){app.quoteTier=e.target.value;$$('.quote-tier').forEach(x=>x.classList.toggle('selected',x.querySelector('input').checked));}if(e.target.id==='school-file'){const label=$('#file-name');if(label)label.textContent=e.target.files[0]?.name||'JPG, PNG, WebP o PDF · máximo 8 MB';}});
document.addEventListener('submit',e=>{if(e.target.id==='quote-form'){e.preventDefault();submitQuote();}});
document.addEventListener('error',e=>{if(e.target.tagName==='IMG'&&e.target.dataset.fallback&&e.target.src!==new URL(e.target.dataset.fallback,location.href).href){e.target.src=e.target.dataset.fallback;}},true);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(app.cartOpen)closeCart();const open=!$('#branch-switch-menu')?.hidden;if(open){closeBranchMenu();$('#branch-switch-btn')?.focus();}}});
window.addEventListener('scroll',()=>{const b=document.documentElement;const d=Math.max(1,b.scrollHeight-b.clientHeight);document.documentElement.style.setProperty('--page-progress',Math.min(100,Math.max(0,window.scrollY/d*100))+'%');},{passive:true});
window.addEventListener('popstate',()=>navigate(location.pathname+location.search,{replace:true,scroll:false}));
window.addEventListener('mousemove',e=>{if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const visual=$('.hero-visual');if(!visual)return;const rect=visual.getBoundingClientRect();const x=(e.clientX-(rect.left+rect.width/2))/rect.width;const y=(e.clientY-(rect.top+rect.height/2))/rect.height;visual.style.setProperty('--mouse-x',`${(x*13).toFixed(2)}px`);visual.style.setProperty('--mouse-y',`${(y*13).toFixed(2)}px`);},{passive:true});
await navigate(location.pathname+location.search,{replace:true});
setInterval(async()=>{if(!app.bootstrap||app.cartOpen)return;try{const current=await api('/api/version');if(current.version!==app.bootstrap.version){app.bootstrap=await api('/api/bootstrap');app.shop=null;await navigate(location.pathname+location.search,{replace:true,scroll:false});}}catch{}},30000);
